parameters.text:
=Analyze the payload below. Determine what type of message it is (alert or notification), extract relevant information, and enrich it appropriately. Use available tools if needed to gather additional context.

### PAYLOAD

{{ JSON.stringify($json.body) }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "message_type": {
      "type": "string",
      "enum": ["alert", "notification"],
      "description": "alert or notification"
    },
    "title": {
      "type": "string",
      "description": "Very short title (e.g., \"Gatus: Plex down\")"
    },
    "severity": {
      "type": "string",
      "enum": ["critical", "warning", "info"]
    },
    "emoji": {
      "type": "string",
      "description": "Single emoji"
    },
    "summary": {
      "type": "string",
      "description": "What happened + what you found from tools. (e.g., \"Plex failed its health check. The plex pod is running but showing connection errors in the logs.\")"
    },
    "context_gathered": {
      "type": "string",
      "description": "Brief bullet points from tool findings. Empty for notifications."
    },
    "suggested_actions": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Only specific actions based on findings. Empty for notifications or if nothing actionable."
    },
    "source": {
      "type": "string",
      "description": "Service/source name"
    }
  },
  "required": ["message_type", "title", "severity", "emoji", "summary", "source"]
}

parameters.jsCode:
// Format enriched message as HTML for Telegram
const output = $json.output;

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const emoji = output.emoji || '🔔';
const title = escapeHtml(output.title || 'Message');
const summary = escapeHtml(output.summary || '');
// const contextGathered = output.context_gathered || '';

// const contextBlock = contextGathered
//   ? '\n\n<b>Context:</b>\n' + escapeHtml(contextGathered)
//   : '';

// const message = emoji + ' <b>' + title + '</b>\n\n' + summary + contextBlock;

const message = emoji + ' <b>' + title + '</b>\n\n' + summary;

// Alerts play sound, notifications are silent
const disableNotification = output.message_type === 'notification';

return {
  json: {
    message: message,
    disableNotification: disableNotification
  }
};

// Format failed summarizer messages as HTML for Telegram
const output = $json.output;

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const title = 'Notification received but AI enrichment failed.';
const message = '🔔 <b>' + title + '</b>\n\n' + escapeHtml(output);

// Fallback always plays sound (assume it's important)
return {
  json: {
    message: message,
    disableNotification: false
  }
};
